css:
.pair{display:grid;grid-template-columns:1fr auto 1fr;gap:24px;align-items:center}
.pair__plus{width:44px;height:44px}  /* 手描きSVG。真円・均等線幅にしないこと */
.pair__sum{grid-column:1/-1;margin-top:18px;background:#6b4ef0;color:#fff;
  border-radius:999px;display:flex;justify-content:space-between;align-items:center;
  padding:14px 20px;font-weight:700}
@media(max-width:768px){.pair{grid-template-columns:1fr;justify-items:center}}
